  color: #435b37;
  margin: 0 7px;
}
.toast {
  position: fixed;
  bottom: 25px;
  left: 50%;
  transform: translateX(-50%);
  background: #2c3b29;
  border: 1px solid #849861;
  color: #ebefd2;
  padding: 13px 22px;
  border-radius: 4px;
  font-size: 12px;
