}
.result-overlay {
  position: absolute;
  inset: 0;
  z-index: 5;
  display: grid;
  place-items: center;
  background: #102017c9;
  backdrop-filter: blur(3px);
}
.result-card {
  text-align: center;
  padding: 25px;
  color: #e4e8c9;
  animation: appear 0.35s;
}
