/* Action forecasts: solid cyan is the immediate shove; violet dashes are next turn. */
.preview-panel {
  margin-top: 16px;
  padding: 14px;
  border: 1px solid #3b4936;
  border-radius: 4px;
  background: #18241c;
}
.preview-panel.has-preview {
  border-color: #648c83;
  background: linear-gradient(135deg, #1d302a, #19251d);
}
.preview-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 10px;
}
.preview-heading h2 {
  font-size: 11px;
  font-weight: 500;
  color: #d5dfbf;
}
.preview-heading > span {
  font-size: 6px;
  letter-spacing: 0.7px;
  color: #8d9e85;
  text-align: right;
}
.preview-empty {
  font-size: 10px;
  line-height: 1.8;
  color: #94a789;
}
.preview-action {
  font-size: 11px;
  color: #9de0df;
  padding-bottom: 10px;
  border-bottom: 1px solid #365044;
}
.preview-earth {
  font-size: 10px;
  line-height: 1.7;
  color: #c3c9ad;
  margin: 10px 0;
}
.preview-panel ul {
  list-style: none;
  padding: 0;
  margin: 0;
}
.preview-panel li {
  padding: 10px 0;
  border-bottom: 1px solid #344536;
}
.preview-panel li > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 5px;
  font-size: 10px;
  color: #d8dfc7;
}
.preview-panel strong {
  font-size: 10px;
  font-weight: 500;
}
.preview-panel li > div > span {
  white-space: nowrap;
  color: #e8caa1;
  font-family: monospace;
}
.preview-panel small {
  display: block;
  font-size: 9px;
  line-height: 1.7;
  color: #a9bba0;
  margin-top: 5px;
}
.preview-panel em {
  font-size: 6px;
  letter-spacing: 0.8px;
  font-style: normal;
  color: #efc57f;
  border: 1px solid #8e734a;
  padding: 2px 3px;
}
.preview-ally strong {
  color: #edc57f;
}
.preview-defeated {
  display: block;
  font-size: 9px;
  font-weight: 500;
  color: #f1a48d;
  margin-top: 5px;
}
.preview-structure strong {
  color: #d9ce96;
}
.preview-next {
  padding-top: 13px;
}
.preview-next h3 {
  font-size: 8px;
  letter-spacing: 1px;
  color: #c6b6ea;
  margin-bottom: 9px;
}
.preview-route {
  margin: 9px 0;
  padding-left: 9px;
  border-left: 2px dashed #a99aca;
}
.preview-route strong,
.preview-route > span {
  display: block;
}
.preview-route > span {
  font-size: 10px;
  color: #d0c3e7;
  margin-top: 5px;
  line-height: 1.6;
}
.preview-next > p {
  font-size: 9px;
  line-height: 1.7;
  color: #94a788;
  margin-top: 12px;
}
.preview-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 7px 10px;
  padding-top: 12px;
  font-size: 7px;
  color: #9eb69d;
}
.preview-legend > span {
  display: flex;
  align-items: center;
  gap: 5px;
}
.preview-legend i {
  width: 7px;
  height: 7px;
  display: inline-block;
}
.preview-push-color {
  border: 1px solid #8be5ed;
  background: #8be5ed44;
}
.preview-path-color {
  border: 1px dashed #cab1ff;
  background: #cab1ff33;
}
.preview-victory {
  font-size: 10px;
  line-height: 1.8;
  color: #deeba9;
  margin-top: 10px;
}
@media (max-width: 680px) {
  .preview-panel {
    margin-top: 14px;
    padding: 14px;
  }
  .preview-heading h2 {
    font-size: 12px;
  }
  .preview-heading > span {
    font-size: 7px;
  }
  .preview-panel strong,
  .preview-panel li > div,
  .preview-route > span {
    font-size: 11px;
  }
  .preview-panel small,
  .preview-next > p {
    font-size: 10px;
  }
  .preview-legend {
    font-size: 8px;
  }
}

