  color: #aebda7;
}
.team-choice {
  margin-top: auto;
  padding-top: 16px;
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.08em;
  color: var(--element);
}
#team-count {
  color: #dedfb6;
  font-size: 13px;
}
.team-restart-note {
  font-size: 11px !important;
  color: #97aa94 !important;
}
.help-elements {
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
}
@media (max-width: 760px) {
  .team-dialog {
    padding: 22px;
  }
  .team-options {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .team-option:last-child {
    grid-column: 1/-1;
  }
  .team-dialog h2 {
